-- RLC_001 only. Reuses explore_content; no schema/RLS changes.
-- UUID primary key; exact RLC ID and source metadata in content_body.
-- approved_for_build -> APPROVED; authoritative_guidance -> EDITORIAL engine source class.
-- Exact Easy difficulty retained in content_body; existing difficulty column left null.
-- Exact reruns do nothing; conflicting existing rows abort.
begin;
lock table public.explore_content in share row exclusive mode;
do $import$
declare
 wanted jsonb := $record${"content_id": "c83886c4-9e1c-5a1b-8e74-57f48b55f848", "content_type": "REAL_LIFE_CHALLENGE", "title": "Label Detective", "subtitle": null, "domain": "KNOW", "topic": "Label reading", "interaction_type": "REFLECTION", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "real_life_challenge_v1", "challenge_id": "RLC_001", "content_type": "REAL_LIFE_CHALLENGE", "domain": "KNOW", "skill": "Label reading", "difficulty": "Easy", "xp_value": "+15", "related_quick_learn_id": "QL_003", "related_practice_id": "PRACTICE_003", "source_type": "authoritative_guidance", "review_status": "approved_for_build", "expert_reviewed": "not required for coding", "medical_review_required": "false", "content_version": "1.0", "active": "true", "title": "Label Detective", "instruction": "Choose one unfamiliar packaged food and practice your label-checking process.", "safety_note": "You do not need to eat or buy the product to complete this challenge.", "completion_message": "You tried the skill. That counts. +15 XP", "source_basis": "FDA; NIDDK", "steps": ["Read the package information instead of judging only by the front.", "Look for a gluten-free claim and relevant ingredient information.", "If you still cannot tell, stop at “I need more information” rather than guessing."], "reflection_options": ["😊 Easier than expected", "🙂 Pretty good", "😐 Okay", "😬 Awkward", "🔄 Didn't go as planned"], "source_url": "https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/eating-diet-nutrition", "related_quick_learn_uuid": "b89f6056-96ac-5248-8bf1-c85369e3cad8", "related_practice_uuid": "4cab56b8-ea49-5204-9dc2-f03df42ab0e5", "original_metadata": {"challenge_id": "RLC_001", "content_type": "REAL_LIFE_CHALLENGE", "domain": "KNOW", "skill": "Label reading", "difficulty": "Easy", "xp_value": "+15", "related_quick_learn_id": "QL_003", "related_practice_id": "PRACTICE_003", "source_type": "authoritative_guidance", "review_status": "approved_for_build", "expert_reviewed": "not required for coding", "medical_review_required": "false", "content_version": "1.0", "active": "true", "title": "Label Detective", "instruction": "Choose one unfamiliar packaged food and practice your label-checking process.", "safety_note": "You do not need to eat or buy the product to complete this challenge.", "completion_message": "You tried the skill. That counts. +15 XP", "source_basis": "FDA; NIDDK", "steps": ["Read the package information instead of judging only by the front.", "Look for a gluten-free claim and relevant ingredient information.", "If you still cannot tell, stop at “I need more information” rather than guessing."], "reflection_options": ["😊 Easier than expected", "🙂 Pretty good", "😐 Okay", "😬 Awkward", "🔄 Didn't go as planned"], "source_url": "https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/eating-diet-nutrition"}}, "choices": [], "feedback": {}, "teaching_point": null, "next_step": null, "related_content_ids": ["b89f6056-96ac-5248-8bf1-c85369e3cad8", "4cab56b8-ea49-5204-9dc2-f03df42ab0e5"], "xp_value": 15, "source_type": "EDITORIAL", "source_organization": "FDA; NIDDK", "source_title": null, "source_url": "https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/eating-diet-nutrition", "author": null, "review_status": "APPROVED", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}$record$::jsonb;
 incoming public.explore_content%rowtype; current_row public.explore_content%rowtype;
begin
 select * into incoming from jsonb_populate_record(null::public.explore_content,wanted);
 if exists(select 1 from public.explore_content where content_body->>'challenge_id'='RLC_001' and content_id<>incoming.content_id) then raise exception 'RLC_001 already uses a different UUID'; end if;
 if not exists(select 1 from public.explore_content where content_id='b89f6056-96ac-5248-8bf1-c85369e3cad8'::uuid and content_type='QUICK_LEARN' and content_body->>'content_id'='QL_003') then raise exception 'Expected QL_003 link is missing'; end if;
 if not exists(select 1 from public.explore_content where content_id='4cab56b8-ea49-5204-9dc2-f03df42ab0e5'::uuid and content_type='PRACTICE_A_SKILL' and content_body->>'scenario_id'='PRACTICE_003') then raise exception 'Expected PRACTICE_003 link is missing'; end if;
 select * into current_row from public.explore_content where content_id=incoming.content_id for update;
 if found then
  if exists(select 1 from jsonb_each(wanted) f where to_jsonb(current_row)->f.key is distinct from f.value) then raise exception 'RLC_001 has different fields. No changes made'; end if;
  return;
 end if;
 insert into public.explore_content (content_id, content_type, title, subtitle, domain, topic, interaction_type, difficulty, estimated_minutes, intro, content_body, choices, feedback, teaching_point, next_step, related_content_ids, xp_value, source_type, source_organization, source_title, source_url, author, review_status, expert_reviewer, medical_review_required, content_version, last_reviewed, active) values (incoming.content_id, incoming.content_type, incoming.title, incoming.subtitle, incoming.domain, incoming.topic, incoming.interaction_type, incoming.difficulty, incoming.estimated_minutes, incoming.intro, incoming.content_body, incoming.choices, incoming.feedback, incoming.teaching_point, incoming.next_step, incoming.related_content_ids, incoming.xp_value, incoming.source_type, incoming.source_organization, incoming.source_title, incoming.source_url, incoming.author, incoming.review_status, incoming.expert_reviewer, incoming.medical_review_required, incoming.content_version, incoming.last_reviewed, incoming.active);
end $import$;
commit;
select content_body->>'challenge_id' as challenge_id,content_id,title,
 jsonb_array_length(content_body->'steps') as step_count,jsonb_array_length(content_body->'reflection_options') as reflection_count,
 xp_value,content_body->>'related_quick_learn_id' as related_quick_learn_id,content_body->>'related_practice_id' as related_practice_id,
 content_body->>'source_type' as original_source_type,content_body->>'review_status' as original_review_status,
 review_status,medical_review_required,content_version,active
from public.explore_content where content_id='c83886c4-9e1c-5a1b-8e74-57f48b55f848'::uuid;
